import type { LexicalEditor } from "lexical";

export function isLexicalEditor(value: unknown): value is LexicalEditor {
  return (
    typeof value === "object" &&
    value !== null &&
    "_editorState" in value &&
    "_rootElement" in value &&
    "_readOnly" in value &&
    typeof (value as any)._readOnly === "boolean"
  );
}

// ===== src/debounce.ts =====
export function debounce<T extends (...args: any[]) => any>(
  fn: T,
  ms: number
): (...args: Parameters<T>) => void {
  let timeoutId: ReturnType<typeof setTimeout> | null = null;

  return function (...args: Parameters<T>) {
    if (timeoutId !== null) {
      clearTimeout(timeoutId);
    }
    timeoutId = setTimeout(() => {
      fn(...args);
    }, ms);
  };
}

